#!/usr/bin/env node
/**
 * Build the standalone page.
 *
 * web/index.html loads the modules with ES imports, which needs a server.
 * This inlines every module into a single file that opens straight from disk —
 * double-click on a laptop, or open it on a phone — with no server, no network
 * and no build tooling at run time.
 *
 *   node scripts/bundle.js        →  web/standalone.html
 *
 * Each module becomes one scoped block that returns its exports, so modules
 * keep their own private names. Anything that is not a named import or a named
 * export is out of scope here, and would need a real bundler.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname.replace(/\/$/, '');

/** Dependency order — a module may only use ones above it. */
const MODULES = [
  'rational.js',
  'pattern.js',
  'tree.js',
  'model.js',
  'methods.js',
  'step.js',
  'graph.js',
  'discover.js',
  'format.js',
];

const IMPORT = /^import\s*\{([^}]*)\}\s*from\s*'\.\/([\w.]+)';?$/gm;
const EXPORT_DECLARATION = /^export\s+(?=(?:const|let|var|function|class|async)\b)/gm;
const EXPORT_LIST = /^export\s*\{([^}]*)\};?$/gm;

/** Turn one module into `const __m_name = (() => { … return {exports}; })();` */
function wrap(source, file) {
  const name = moduleName(file);
  const exported = new Set();

  let body = source.replace(IMPORT, (_, names, from) => {
    const wanted = names
      .split(',')
      .map((entry) => entry.trim())
      .filter(Boolean)
      .join(', ');
    return `const { ${wanted} } = ${moduleName(from)};`;
  });

  // collect names from `export function foo` / `export const bar` …
  for (const match of body.matchAll(
    /^export\s+(?:async\s+)?(?:function\*?|class|const|let|var)\s+([A-Za-z_$][\w$]*)/gm,
  )) {
    exported.add(match[1]);
  }
  for (const match of body.matchAll(EXPORT_LIST)) {
    for (const entry of match[1].split(',')) {
      const cleaned = entry.trim().split(/\s+as\s+/).pop();
      if (cleaned) exported.add(cleaned);
    }
  }

  body = body.replace(EXPORT_DECLARATION, '').replace(EXPORT_LIST, '');

  return [
    `/* ---- src/${file} ---- */`,
    `const ${name} = (() => {`,
    body.trim(),
    `return { ${[...exported].join(', ')} };`,
    '})();',
  ].join('\n');
}

const moduleName = (file) => `__m_${file.replace(/\W/g, '_')}`;

/**
 * Drop the document wrapper, keeping the title, styles and content.
 * Some hosts wrap the content in their own <html>/<head>/<body>, and nesting a
 * second document inside that would be invalid.
 */
function stripDocument(html) {
  const title = /<title>[\s\S]*?<\/title>/.exec(html)?.[0] ?? '';
  const style = /<style>[\s\S]*?<\/style>/.exec(html)?.[0] ?? '';
  const body = /<body>([\s\S]*)<\/body>/.exec(html)?.[1] ?? '';
  return [title, style, body.trim()].filter(Boolean).join('\n');
}

async function build() {
  const blocks = [];
  const everything = new Set();

  for (const file of MODULES) {
    const source = await readFile(join(ROOT, 'src', file), 'utf8');
    blocks.push(wrap(source, file));
    for (const match of source.matchAll(
      /^export\s+(?:async\s+)?(?:function\*?|class|const|let|var)\s+([A-Za-z_$][\w$]*)/gm,
    )) {
      everything.add([match[1], moduleName(file)]);
    }
  }

  const roster = [...everything]
    .map(([name, module]) => `  ${name}: ${module}.${name},`)
    .join('\n');
  blocks.push(`const AiTree = {\n${roster}\n};`);

  const page = await readFile(join(ROOT, 'web', 'index.html'), 'utf8');
  const bundled = page.replace(
    /^import \{([^}]*)\} from '\.\.\/src\/index\.js';$/m,
    (_, names) => `${blocks.join('\n\n')}\n\nconst {${names}} = AiTree;`,
  );

  if (bundled === page) {
    throw new Error('could not find the import line in web/index.html');
  }

  const note = '<!-- generated by scripts/bundle.js — edit web/index.html instead -->\n';
  await writeFile(join(ROOT, 'web', 'standalone.html'), note + bundled);
  console.log(`web/standalone.html — ${(note.length + bundled.length) / 1024 | 0} kB, no server needed`);

  // a body-only copy, for hosts that supply their own document shell
  const fragment = note + stripDocument(bundled);
  await writeFile(join(ROOT, 'web', 'embed.html'), fragment);
  console.log(`web/embed.html — ${fragment.length / 1024 | 0} kB, no document wrapper`);
}

build().catch((error) => {
  console.error(`bundle failed: ${error.message}`);
  process.exitCode = 1;
});
